import React from 'react';

import type {RenderPreviewParams} from '@gravity-ui/markdown-editor';
import {YfmStaticView} from '@gravity-ui/markdown-editor/view';
import transform from '@diplodoc/transform';

import '@diplodoc/transform/dist/css/yfm.css';

type MarkdownPreviewProps = RenderPreviewParams;

const renderDelay = 200;

export function MarkdownPreview({getValue, md}: MarkdownPreviewProps) {
  const [html, setHtml] = React.useState('');
  const previousValue = React.useRef<string | null>(null);

  React.useEffect(() => {
    const render = () => {
      const value = String(getValue());

      if (previousValue.current === value) {
        return;
      }

      previousValue.current = value;
      setHtml(
        transform(value, {
          allowHTML: false,
          breaks: md.breaks,
          linkify: md.linkify,
          linkifyTlds: md.linkifyTlds,
        }).result.html,
      );
    };

    render();
    const timerId = window.setTimeout(render, renderDelay);

    return () => window.clearTimeout(timerId);
  }, [getValue, md]);

  return <YfmStaticView className=\"markdown-preview\" html={html} noListReset />;
}
EOF
cat > src/App.tsx <<'EOF'
import React from 'react';

import {
  configure,
  useMarkdownEditor,
  MarkdownEditorView,
  type RenderPreview,
  type MarkupString,
} from '@gravity-ui/markdown-editor';
import {Button, Card, Text} from '@gravity-ui/uikit';

import './App.css';
import {MarkdownPreview} from './MarkdownPreview';

configure({lang: 'ru'});

const initialMarkdown = "'`# Описание'"\\n\\nПоддерживается **жирный текст**, *курсив*, [ссылки](https://example.com) и списки:\\n\\n- первый пункт\\n- второй пункт\\n"'`;

export function App() {
  const [submittedMarkdown, setSubmittedMarkdown] = React.useState<MarkupString>();

  const renderPreview = React.useCallback<RenderPreview>(
    ({getValue, md}) => <MarkdownPreview getValue={getValue} md={md} />,
    [],
  );

  const editor = useMarkdownEditor({
    allowHTML: false,
    initialEditorMode: '"'wysiwyg',
    initialSplitModeEnabled: true,
    initialToolbarVisible: true,
    splitMode: 'horizontal',
    markup: initialMarkdown,
    renderPreview,
  });

  const handleSubmit = React.useCallback(() => {
    setSubmittedMarkdown(editor.getValue());
  }, [editor]);

  React.useEffect(() => {
    const handleSubmitEvent = () => setSubmittedMarkdown(editor.getValue());

    editor.on('submit', handleSubmitEvent);

    return () => {
      editor.off('submit', handleSubmitEvent);
    };
  }, [editor]);

  return (
    <div className=\"app\">
      <Card className=\"app-card\" type=\"container\" view=\"outlined\">
        <Text as=\"h1\" variant=\"header-2\">
          Статья
        </Text>

        <form onSubmit={handleSubmit}>
          <MarkdownEditorView editor={editor} stickyToolbar autofocus />

          <div className=\"app-actions\">
            <Button type=\"submit\" view=\"action\">
              Сохранить
            </Button>
          </div>
        </form>

        {submittedMarkdown "'!== undefined && (
          <Text color="secondary" variant="body-2">
            Markdown сохранён ({String(submittedMarkdown).length} символов)
          </Text>
        )}
      </Card>
    </div>
  );
}
EOF
